export default '/**\n * Stackra file contract:\n * Purpose: the "compare" demo of the native PeriodPicker: this quarter compared with the previous one; the switch reads\n *          the comparison range and the mode Select turns it into the same quarter last year.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decisions 3 and 5);\n *          ADR 0060 (light, dark, RTL); STA-1371.\n */\nimport { CalendarDate } from "@internationalized/date";\nimport { PeriodPicker, useCatalogueText } from "@stackra/ui/native";\nimport { View } from "react-native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { PERIOD_PICKER_DEMO_KEYS } from "#src/demos/free/period-picker/period-picker-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = PERIOD_PICKER_DEMO_KEYS.demo_free.period_picker;\n\n/** Period picker: compare. */\nexport default function Compare() {\n  const t = useCatalogueText(MESSAGES.en);\n  return (\n    <View className="gap-4">\n      <PeriodPicker\n        label={t(K.label)}\n        today={new CalendarDate(2026, 10, 29)}\n        defaultValue={{\n          preset: "this_quarter",\n          range: { start: new CalendarDate(2026, 10, 1), end: new CalendarDate(2026, 12, 31) },\n          compare: {\n            mode: "previous",\n            range: { start: new CalendarDate(2026, 7, 1), end: new CalendarDate(2026, 9, 30) },\n          },\n        }}\n      />\n    </View>\n  );\n}\n';
